Envoy Proxy API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(envoy_proxy_api_gateway, "Envoy Proxy API Gateway") {
    Component(Edge_Router, "Edge Router", "Envoy Proxy", "Handles edge routing, rate limiting, and TLS 1.3 termination for high performance and security.")
    Component(Authentication_Filter, "Authentication Filter", "OAuth2-Proxy / Keycloak", "Performs zero-trust token inspection and identity management via internal token validation.")
}

Rel(Edge_Router, Authentication_Filter, "Internal token validation", "Internal HTTP / mTLS")

@enduml

OAuth2-Proxy / Keycloak Sidecar.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("OAuth2-Proxy_Keycloak_Sidecar", "OAuth2-Proxy / Keycloak Sidecar") {
    Component("OAuth2-Proxy Authentication Handler", "OAuth2-Proxy Authentication Handler", "Go (OAuth2-Proxy)", "Lightweight, stateless authentication sidecar handling token validation, session management, and intercepting requests from the Envoy Proxy.")
    Component("Local JWKS Caching Module", "Local JWKS Caching Module", "In-Memory Go Cache", "Caches JSON Web Key Sets locally to validate tokens swiftly and minimize latency against the Enterprise IdP.")
}

Rel("OAuth2-Proxy Authentication Handler", "Local JWKS Caching Module", "Queries cached public keys for JWT validation", "In-memory")

@enduml

FHIR Interoperability Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fhir_interoperability_gateway, "FHIR Interoperability Gateway") {
    Component(HAPI_FHIR_JPA_Server_Engine, "HAPI FHIR JPA Server Engine", "Java / Spring Boot, HAPI FHIR JPA Server", "Handles standards-compliant clinical endpoints and HL7 FHIR API requests.")
    Component(Kafka_Event_Producer, "Kafka Event Producer", "Apache Kafka Producer API", "Publishes clinical and operational events to Apache Kafka asynchronously.")
    Component(Data_Persistence_Manager, "Data Persistence Manager", "JDBC, HikariCP", "Manages data persistence connections to the PostgreSQL database with AES-256 encryption.")
    Component(Session_and_Token_Caching_Manager, "Session and Token Caching Manager", "Redis Protocol Client", "Handles distributed token caching and session state management via Redis.")
}

Rel(HAPI_FHIR_JPA_Server_Engine, Kafka_Event_Producer, "Publishes event messages", "Kafka Producer API")
Rel(HAPI_FHIR_JPA_Server_Engine, Data_Persistence_Manager, "Reads and writes clinical data", "JDBC over TLS")
Rel(HAPI_FHIR_JPA_Server_Engine, Session_and_Token_Caching_Manager, "Caches tokens and session state", "Redis Protocol")
@enduml

Apache Kafka.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(apache_kafka, "Apache Kafka") {
    Component(Kafka_Broker, "Kafka Broker", "Java/Scala with KRaft", "Handles distributed event streaming and message brokering using KRaft mode.")
    Component(Schema_Registry, "Schema Registry", "Confluent", "Provides Avro and Protobuf schema validation and data masking.")
    Component(Tiered_Storage_Manager, "Tiered Storage Manager", "Native plug-in API over TLS 1.3", "Offloads logs to AWS S3 for long-term data retention.")
    Component(Kafka_MirrorMaker_2_MM2_, "Kafka MirrorMaker 2 (MM2)", "Kafka Connect / MM2", "Manages asynchronous cross-site replication between on-prem-k8s and AWS.")
}

Rel(Kafka_Broker, Schema_Registry, "Validates Avro and Protobuf schemas and masks data via HTTPS.", "HTTPS")
Rel(Kafka_Broker, Tiered_Storage_Manager, "Offloads logs to AWS S3 using AWS IRSA over TLS 1.3.", "TLS 1.3")
Rel(Kafka_Broker, Kafka_MirrorMaker_2_MM2_, "Replicates event streams asynchronously across sites.", "Kafka Connect / MM2")
@enduml
